head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.keyIsurCd, scwin.keyGubun;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // alert(0);
        gform.scroll = "no";
        const arrPar = new Array();
        const prt = $c.frame.path("../");
        if (prt !== undefined) {
            // alert(1);
            scwin.fn_GetPar = prt.scwin.fn_GetPar;
            scwin.fn_SetPar = prt.scwin.fn_SetPar;
        }
        if (scwin.fn_GetPar !== undefined) {
            // alert(2);
            scwin.fn_GetPar(arrPar, dts_selectleadcom);
            scwin.keyIsurCd = (arrPar.length >= 1 ? arrPar[0] : "");
            scwin.keyGubun = (arrPar.length >= 2 ? arrPar[1] : "");

            // 채권 종목 조회
            scwin.setCode();
        }
        // alert(dts_selectleadcom.countrow);

        // txb_SelCnt.value = "선택건수 : " + dts_selectleadcom.countrow ;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90031.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_code_OnLoadCompleted
 * @description dts_code 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_code_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총건수 : " + rowcount);
        scwin.setSelCnt();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90031.dts_code_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function() {
    try {
        await scwin.confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90031.btn_confirm_onclick" });
    }
};

/**
 * @method
