/**
 * @method
 * @name img_rightarr_onclick
 * @description img_rightarr 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_rightarr_onclick = async function() {
    try {
        if (dts_code.getRowCount() === 0) {
            await $c.win.alert("데이터가 없습니다.");
            return;
        }
        scwin.add();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90031.img_rightarr_onclick" });
    }
};

