///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name addDtsSelect
 * @description dts_code의 인덱스에 해당하는 값을 dts_selectleadcom에 add한다.
 * @param {*} add_index add_index
 * @returns {void}
 * @hidden N
 */
scwin.addDtsSelect = function(add_index) {
    dts_selectleadcom.insertRow();
    // alert(add_index+'::'+dts_selectleadcom.NameValue(dts_selectleadcom.RowPosition , "ISU_SEQ")+'::'+dts_code.NameValue(add_index,"ISU_SEQ"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_CD", dts_code.getCellData(add_index, "STD_CD")); // 종목코드 이름이 다름
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_NM", dts_code.getCellData(add_index, "ISU_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISUR_CD", dts_code.getCellData(add_index, "ISUR_CD"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISUR_NM", dts_code.getCellData(add_index, "ISUR_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "COM_NM", dts_code.getCellData(add_index, "COM_NM"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_SEQ", dts_code.getCellData(add_index, "ISU_SEQ"));
    dts_selectleadcom.setCellData(dts_selectleadcom.getRowPosition(), "ISU_DD", dts_code.getCellData(add_index, "ISU_DD"));
};

/**
 * @method
 * @name add
 * @description add 처리
 * @returns {void}
 * @hidden N
 */
scwin.add = function() {
    for (i = 1; i <= dts_selectleadcom.getRowCount(); i++) {
        if (dts_selectleadcom.getCellData(i, "ISU_CD") === dts_code.getCellData(dts_code.getRowPosition(), "STD_CD")) {
            return;
        }
    }
    scwin.addDtsSelect(dts_code.getRowPosition());
    dts_selectleadcom.sort("+ISU_DD", 0);
    // dts_selectleadcom.sort(); // W-Craft 주석처리
    scwin.setSelCnt();
};

/**
 * @method
 * @name addAll
 * @description add All 처리
 * @returns {void}
 * @hidden N
 */
scwin.addAll = function() {
    dts_selectleadcom.removeAll();
    grd_selectleadcom.redraw = false;
    for (i = 1; i <= dts_code.getRowCount(); i++) {
        scwin.addDtsSelect(i);
    }
    grd_selectleadcom.redraw = true;
    grd_selectleadcom.focus();
    dts_selectleadcom.setRowPosition("1", 0);
    scwin.setSelCnt();

    // dts_selectleadcom.SortExpr="+ISU_NM";
    // dts_selectleadcom.Sort();

};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    // var RowPos = dts_selectleadcom.ValueRow(dts_selectleadcom.RowPosition, MTr_2.ItemText);
    const RowPos = dts_selectleadcom.getRowPosition();
    dts_selectleadcom.removeRow(RowPos);
    scwin.setSelCnt();
};

/**
 * @method
 * @name delAll
 * @description del All 처리
 * @returns {void}
 * @hidden N
 */
scwin.delAll = function() {
    dts_selectleadcom.removeAll();
    scwin.setSelCnt();
};

/**
 * @method
 * @name setSelCnt
 * @description set Sel Cnt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setSelCnt = function() {
    txb_SelCnt.setValue("선택건수 : " + dts_selectleadcom.getRowCount());
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    scwin.fn_SetPar(dts_selectleadcom);
    await $c.win.closePopup();
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // dts_code.DataID = "/etn/EtnCodeAct.do?method=searchEtnCode&GUBUN=" + keyGubun + "&ISUR_CD=" + keyIsurCd ;
    // dts_code.Reset();
    let param = '';
    param += "&{P}V_ISUR_NM=" + scwin.keyIsurCd; // 발행기관코드
    param += "&{P}V_ISU_NM=";
    param += "&{P}V_LIST_TYPE_CD=1"; // 상장채권만 조회

    // alert(param);

    const dsNm = 'BNS_LIST_BND_POP';
    const qryId = 'lds.stf.bnslistcrchl.select.listListBndIsu';
    $c.bns.fn_SearchBns("ULDBNS90031.xml", dts_code, dsNm, qryId, param);
    dts_code.Reset();
};
